/**
 * The props passed to a custom `paramsTemplate` component for the `ToolCall` component.
 *
 * When a `paramsTemplate` is provided, it replaces the default JSON parameters rendering.
 */
export interface ToolCallParamsTemplateProps {
    /** The raw tool input / parameter data. */
    parameters: unknown;
}
